//! 🧪️ One admitted caller retains the original source stock through native birth, callback receipts and terminal closure.
use super::*;
pub(super) const STOCK:RetainedCloneGrant=RetainedCloneGrant{maximum_items:20000,maximum_copy_bytes:16777216,maximum_capacity_bytes:16777216,maximum_release_bytes:16777216,maximum_depth:128};
pub(super) struct Fixture<J:InteractiveJob>{pub owner:OriginalWorkerJobAuthority<J>,pub caller:OriginalJobFixtureCaller}
impl<J:InteractiveJob> Fixture<J>{
 pub fn admit(job:J,mut params:BatchJobParams)->Self{let mut caller=OriginalJobFixtureCaller::admit(params.operation,params.generation,STOCK,logical_now_us,u64::MAX,20000);let old=std::mem::replace(&mut params.cancel,caller.admit_alias(STOCK));let mut old=semio_framework_async::CancelTokenRetirement::from_token(old);while !old.terminal_is_empty(){old.close_step(STOCK).unwrap();}let mut job=Some(job);let mut params=Some(params);let owner=caller.turn(STOCK,|cx|Ok(OriginalWorkerJobAuthority::try_admit_owned(&mut job,&mut params,cx)?.unwrap().0)).unwrap();assert!(job.is_none()&&params.is_none());Self{owner,caller}}
 pub fn callback(&mut self,grant:RetainedCloneGrant)->bool{self.owner.stage_callback(grant);let terminal=self.owner.run_staged_callback();let(issued,receipt)=self.owner.take_retained_step_receipt().unwrap();assert_eq!(issued,grant);assert!(receipt.fits(grant));self.caller.turn(STOCK,|cx|{cx.consume_retained(receipt)?;cx.consume_fuel(1);Ok(())}).unwrap();terminal}
 pub fn acknowledge(&mut self){for _ in 0..4{if self.owner.original.outcome.is_empty(){break}self.caller.turn(STOCK,|cx|{let step=self.owner.acknowledge_outcome(cx.retained_grant());cx.consume_retained(step.progress())?;cx.consume_fuel(1);Ok(())}).unwrap();}assert!(self.owner.original.outcome.is_empty());}
 pub fn close(mut self){for _ in 0..512{if self.owner.terminal_is_empty(){break}self.caller.turn(STOCK,|cx|{if self.owner.has_original_cancel_alias_witness(cx.original_cancel_token()){let step=self.owner.return_original_cancel_alias_step(cx.original_cancel_token(),cx.retained_grant()).map_err(|error|match error{semio_framework_async::CancelTokenRetirementError::Refused(error)=>OriginalTurnFailure::from(error),semio_framework_async::CancelTokenRetirementError::Blocked(_)=>OriginalTurnFailure::from(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original authority fixture alias blocked"))})?.unwrap();cx.consume_retained(step.progress())?;cx.consume_fuel(1);}else{self.owner.close_step(cx)?;}Ok(())}).unwrap();}assert!(self.owner.terminal_is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(self.owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));self.caller.retire(STOCK);}
}
